import {PETS,addMaterial,spendMaterials,canMaterials} from './economy.mjs?v=0.6';
import {petSlotCount,deployedPets} from './pet-data.mjs?v=0.6';
import {regionUnlocked} from './regions.mjs?v=0.6';
export function migrateRoster(s){if(!s.petRoster){s.petRoster=[];s.petNextId=1;s.petDeck=[];for(const[k,rank]of Object.entries(s.petLevels))if(rank>0){const it={id:'pet-'+s.petNextId++,species:k,rank,treasure:s.companions?.treasures[k]||0,protected:false};s.petRoster.push(it);if(k===s.spirit)s.petDeck.push(it.id);}}return s;}
export function validateRoster(s){if(s.petRoster===undefined)return;if(!Array.isArray(s.petRoster)||s.petRoster.length>500||new Set(s.petRoster.map(p=>p.id)).size!==s.petRoster.length||s.petRoster.some(p=>!p||!/^pet-[1-9]\d*$/.test(p.id)||!Object.hasOwn(PETS,p.species)||!Number.isInteger(p.rank)||p.rank<1||p.rank>5||!Number.isInteger(p.treasure)||p.treasure<0||p.treasure>3||typeof p.protected!=='boolean'))throw Error('Kho pet không hợp lệ');if(!Number.isSafeInteger(s.petNextId)||s.petNextId<=Math.max(0,...s.petRoster.map(p=>+p.id.slice(4))))throw Error('Mã pet không hợp lệ');if(!Array.isArray(s.petDeck)||s.petDeck.length>petSlotCount(s)||new Set(s.petDeck).size!==s.petDeck.length||s.petDeck.some(id=>!s.petRoster.some(p=>p.id===id)))throw Error('Đội pet không hợp lệ');const kinds=s.petDeck.map(id=>s.petRoster.find(p=>p.id===id).species);if(new Set(kinds).size!==kinds.length)throw Error('Mỗi loài chỉ triển khai một pet');}
export const rosterActions={
 upgradePet(species){if(!Object.hasOwn(PETS,species)||!regionUnlocked(this.s,PETS[species].unlock))return false;let it=this.s.petRoster.find(p=>p.species===species);const lv=it?.rank||0,grade=PETS[species].grade,gold=100+lv*90;if(lv>=5||this.s.gold<gold||!canMaterials(this.s,{essence:lv+2},grade)||!it&&this.s.petRoster.length>=500)return false;spendMaterials(this.s,{essence:lv+2},grade);this.s.gold-=gold;if(it)it.rank++;else{it={id:'pet-'+this.s.petNextId++,species,rank:1,treasure:0,protected:false};this.s.petRoster.push(it);}this.syncPetLegacy();return true;},
 choosePet(species){const it=this.s.petRoster.find(p=>p.species===species);if(!it)return false;this.s.petDeck=this.s.petDeck.filter(id=>this.s.petRoster.find(p=>p.id===id)?.species!==species);if(this.s.petDeck.length>=petSlotCount(this.s))this.s.petDeck.pop();this.s.petDeck.unshift(it.id);this.syncPetLegacy();return true;},
 selectSpirit(species){return this.choosePet(species);},
 spiritUpgrade(species){if(this.s.quest<6||!['fox','crane','turtle'].includes(species))return false;const ok=this.upgradePet(species);if(ok)this.choosePet(species);return ok;},
 upgradeTreasure(species){const it=this.s.petRoster.find(p=>p.species===species);return it?this.raisePet(it.id,true):false;},
 rosterPulse(){if(this.s.companions.stance==='passive')return;const s=this.s;for(const it of deployedPets(s)){const k=PETS[it.species].shape,lv=it.rank,tr=it.treasure,near=this.enemies.filter(e=>!e.dead&&this.unlocked(e)&&Math.hypot(e.x-s.x,e.z-s.z)<12),targets=s.companions.stance==='defend'?near.filter(e=>e.wind>0||Math.hypot(e.x-s.x,e.z-s.z)<e.range+2):near;if(['crane','deer'].includes(k)){const heal=Math.max(0,Math.min(this.getStats().hp-s.hp,8+lv*5+tr*4));s.hp+=heal;if(heal)this.emit('heal',{x:s.x,z:s.z,amount:heal});if(k==='deer')s.mp=Math.min(this.getStats().mp,s.mp+6);continue;}if(k==='turtle'){if(targets.length)this.ward=Math.max(this.ward,.5+tr*.1);continue;}for(const e of targets.sort((a,b)=>Math.hypot(a.x-s.x,a.z-s.z)-Math.hypot(b.x-s.x,b.z-s.z)).slice(0,['phoenix','dragon'].includes(k)?3:1)){this.hit(e,Math.round((8+lv*7+tr*5)*(k==='dragon'?1.4:k==='wolf'?1.2:1)),'spirit');if(k==='tiger'&&!e.dead)e.stun=Math.max(e.stun||0,.6);}}},
 summonPet(species){const p=PETS[species];if(!Object.hasOwn(PETS,species)||!regionUnlocked(this.s,p.unlock)||this.s.petRoster.length>=500)return false;const gold=100*(p.grade+1),materials={essence:10*(p.grade+1)};if(this.s.gold<gold||!canMaterials(this.s,materials,p.grade))return false;spendMaterials(this.s,materials,p.grade);this.s.gold-=gold;const it={id:'pet-'+this.s.petNextId++,species,rank:1,treasure:0,protected:false};this.s.petRoster.push(it);this.syncPetLegacy();return it;},
 syncPetLegacy(){for(const k of Object.keys(PETS)){this.s.petLevels[k]=Math.max(0,...this.s.petRoster.filter(p=>p.species===k).map(p=>p.rank));this.s.companions.treasures[k]=Math.max(0,...this.s.petRoster.filter(p=>p.species===k).map(p=>p.treasure));}for(const k of ['fox','crane','turtle'])this.s.spirits[k]=this.s.petLevels[k];this.s.spirit=deployedPets(this.s)[0]?.species||'fox';},
 deployPet(id){const it=this.s.petRoster.find(p=>p.id===id);if(!it||this.s.petDeck.includes(id)||this.s.petDeck.length>=petSlotCount(this.s)||deployedPets(this.s).some(p=>p.species===it.species))return false;this.s.petDeck.push(id);this.syncPetLegacy();this.spiritClock=0;return true;},
 removePet(id){this.s.petDeck=this.s.petDeck.filter(k=>k!==id);this.syncPetLegacy();return true;},
 protectPet(id){const p=this.s.petRoster.find(p=>p.id===id);if(!p)return false;p.protected=!p.protected;return true;},
 raisePet(id,treasure=false){const it=this.s.petRoster.find(p=>p.id===id);if(!it)return false;const lv=treasure?it.treasure:it.rank,cap=treasure?3:5;if(lv>=cap)return false;const grade=PETS[it.species].grade,gold=120*(lv+1),materials=treasure?{gem:3*(lv+1),essence:2*(lv+1)}:{essence:3*(lv+1)};if(this.s.gold<gold||!canMaterials(this.s,materials,grade))return false;spendMaterials(this.s,materials,grade);this.s.gold-=gold;if(treasure)it.treasure++;else it.rank++;this.syncPetLegacy();return true;},
 canFusePets(ids){if(!Array.isArray(ids)||ids.length!==4||new Set(ids).size!==4)return false;const list=ids.map(id=>this.s.petRoster.find(p=>p.id===id));return list.every(p=>p&&!p.protected&&!this.s.petDeck.includes(p.id))&&PETS[list[0].species].grade<4&&list.every(p=>PETS[p.species].grade===PETS[list[0].species].grade);},
 fusePets(ids){if(!this.canFusePets(ids))return false;const old=PETS[this.s.petRoster.find(p=>p.id===ids[0]).species].grade,promoted=this.random()<.2,grade=old+Number(promoted),choices=Object.keys(PETS).filter(k=>PETS[k].grade===grade),species=choices[Math.min(choices.length-1,Math.floor(this.random()*choices.length))];this.s.petRoster=this.s.petRoster.filter(p=>!ids.includes(p.id));const it={id:'pet-'+this.s.petNextId++,species,rank:1,treasure:0,protected:false};this.s.petRoster.push(it);this.syncPetLegacy();this.say(promoted?'Ghép pet thành công lên màu mới!':'Ghép nhận một pet cùng màu.');return {item:it,promoted};}
};
